cat > ~/warstwy.sh <<'EOF'
#!/bin/bash
host=$1; port=$2
ip route get "$host" >/dev/null 2>&1 && echo "L3 trasa: OK" || { echo "L3 trasa: BLAD"; exit 1; }
ping -c1 -W2 "$host" >/dev/null 2>&1 && echo "L3 ping: OK" || echo "L3 ping: BRAK (ICMP moze byc blokowany)"
nc -z -w3 "$host" "$port" && echo "L4 port $port: OK" || { echo "L4 port $port: BLAD"; exit 1; }
EOF
chmod +x ~/warstwy.sh
~/warstwy.sh 192.168.56.10 8080
~/warstwy.sh 192.168.56.10 5432
